package hu.boltseged.shipment;
import hu.boltseged.account.Account; import org.junit.jupiter.api.Test; import java.math.*; import java.time.*; import java.util.*; import static org.junit.jupiter.api.Assertions.*;
class ShipmentDomainTest { @Test void multipackIsOneShipmentWithSeparatePackages(){Account a=new Account("x","x@example.com","hash","CUSTOMER");Shipment s=new Shipment(a,"key","P",LocalDate.now(),"{}","{}",List.of(new Shipment.PackageInput(BigDecimal.ONE,BigDecimal.TEN,BigDecimal.TEN,BigDecimal.TEN),new Shipment.PackageInput(BigDecimal.TWO,BigDecimal.TEN,BigDecimal.TEN,BigDecimal.TEN)));s.price(new BigDecimal("100"),new BigDecimal("110"));assertEquals(1,1);assertEquals(2,s.getPackages().size());assertEquals(new BigDecimal("110"),s.getCustomerPrice());s.invoice();assertEquals("INVOICED",s.getBillingStatus());} }
